"""Build a local VI proposal from the supplied source assets. No business services."""
from pathlib import Path
import json
import shutil

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]
OUT = ROOT / 'output' / 'wqt-vi-v2'
OUT.mkdir(parents=True, exist_ok=True)
shutil.copytree(HERE / 'assets', OUT / 'assets', dirs_exist_ok=True)

def img(name, cls='', alt=''):
    return f'<img class="{cls}" src="assets/{name}" alt="{alt}">'

def logo(cls='logo'):
    return img('company-mark.png', cls, '伍仟天科技原有简洁公司标识')

def portal(cls='', variant='blue'):
    return f'''<svg class="portal {cls}" viewBox="0 0 620 620" fill="none" aria-hidden="true">
    <defs><linearGradient id="g-{cls}-{variant}" x1="0" y1="0" x2="620" y2="620" gradientUnits="userSpaceOnUse"><stop stop-color="#337CFF"/><stop offset="1" stop-color="#123CB1"/></linearGradient></defs>
    <path d="M139 64H584L481 556H36Z M166 99H540L453 521H80Z" fill="{'#fff' if variant=='white' else '#337CFF'}" fill-rule="evenodd"/>
    <path d="M203 126H513L440 490H128Z" stroke="{'#acc8ff' if variant=='white' else '#8DB8FF'}" stroke-width="2"/>
    <path d="M260 189H448L400 427H212Z" stroke="{'#acc8ff' if variant=='white' else '#337CFF'}" stroke-width="2"/>
    <path d="M104 382H460M198 136V484" stroke="{'#acc8ff' if variant=='white' else '#337CFF'}" stroke-opacity=".24" stroke-dasharray="3 7"/>
    <circle cx="352" cy="303" r="62" fill="#F47B42"/><path d="M334 303H370M352 285V321" stroke="white" stroke-width="3"/>
    <circle cx="539" cy="78" r="8" fill="#F47B42"/>
    </svg>'''

def footer(n, label):
    return f'<footer><span>WQT · BRAND IDENTITY STUDY</span><span>{label}</span><span>{n:02d} / 10</span></footer>'

def page(n, label, body, cls=''):
    return f'<section class="board {cls}" id="board-{n}">{body}{footer(n,label)}</section>'

