JS=r'''
const feedback=document.querySelector('#demo-feedback');
document.querySelector('#demo-action').addEventListener('click',()=>{feedback.textContent='已选择合作方向 · 本地状态样板，不发送或保存信息。';feedback.style.borderLeftColor='#1d6b4f';});
document.querySelector('#demo-reset').addEventListener('click',()=>{feedback.textContent='选择一个行动，获得即时且有意义的反馈。';feedback.style.borderLeftColor='#337cff';});
document.querySelector('#play-motion').addEventListener('click',()=>{const el=document.querySelector('#motion-window');el.classList.remove('playing');requestAnimationFrame(()=>requestAnimationFrame(()=>el.classList.add('playing')));});
'''
html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>伍仟天 VI 视觉系统提案 V2</title><style>'+CSS+'</style></head><body>'+''.join(pages)+'<script>'+JS+'</script></body></html>'
(OUT/'vi-proposal.html').write_text(html,encoding='utf-8')
(OUT/'build-manifest.json').write_text(json.dumps({'boards':10,'size':[1280,800],'scope':'VI proposal, not website','source_assets':len(list((OUT/'assets').iterdir()))},ensure_ascii=False,indent=2),encoding='utf-8')
print(str(OUT/'vi-proposal.html'))
